-- Athena saved query (Product_B2C_Intl)
-- ID: e6041020-ea7d-498b-9347-77bb9ec975d8
-- Name: Transaction Distribution wrt Ratings - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH target_routes AS ( SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (733, 807), (462, 130), (807, 733), (313, 979), (979, 313), (130, 444), (309, 130), (130, 571), (122, 602), (602, 122), (141, 126), (646, 130), (74706, 74820), (126, 141), (233, 123), (551, 472), (571, 130), (733, 1290), (551, 473), (473, 551), (1290, 733), (122, 129), (472, 551), (130, 79546), (71929, 141), (124, 125), (90883, 74701), (470, 551), (236, 122), (74701, 90883), (125, 124), (1443, 807), (807, 70015), (807, 1443), (313, 1001), (71756, 123), (807, 1290), (129, 122), (313, 94152), (467, 123), (979, 1001), (244, 122), (123, 467), (1001, 313), (293, 122), (443, 979), (979, 443), (455, 123), (1001, 81826), (1001, 979), (123, 455), (141, 216), (94152, 313), (602, 141), (201668, 74706), (443, 70024), (70024, 83760), (1290, 70015) ) AS t(s, d) ), base_data AS ( /* Pre-calculating IST timestamps to make the final SELECT cleaner */ SELECT UPPER(t.user_type) AS user_type, CASE WHEN t.sales_channel = 'RB:MOBILEWEB#droidapp' THEN 'Android' WHEN t.sales_channel = 'RB:MOBILEWEB#iosapp' THEN 'iOS' WHEN t.sales_channel = 'WEBDIRECT' THEN 'Desktop' WHEN t.sales_channel = 'MOBILEWEB' THEN 'MobWeb' END AS sales_channel, CASE WHEN t.is_ac = True THEN 'AC' WHEN t.is_ac = False THEN 'non-AC' END AS is_ac, t.tin, t.mri_session_id, t.route_id, DATE_ADD('minute', 330, t.date_of_issue) as issue_ist, DATE_ADD('minute', 330, t.date_of_journey) as journey_ist FROM "transaction"."bus_ticket_events" t INNER JOIN target_routes tr ON t.source_location_id = tr.src_id AND t.destination_location_id = tr.dest_id WHERE t.time_of_event >= TIMESTAMP '2025-12-31 18:30:00' AND t.time_of_event < TIMESTAMP '2026-01-31 18:30:00' AND t.country_code = 'IND' AND t.event_class = 2 AND t.event_type = 101 AND business_unit IN ('REDBUS_IN') AND sales_channel IN ('RB:MOBILEWEB#droidapp', 'RB:MOBILEWEB#iosapp', 'WEBDIRECT', 'MOBILEWEB') ), ratings AS ( SELECT s.mri_session_id, s.route_id, MAX(total_ratings) total_ratings FROM "user_interaction"."search_route_details" s INNER JOIN base_data t ON s.mri_session_id = t.mri_session_id AND s.route_id = t.route_id WHERE s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-31 18:30:00' AND s.country = 'IND' AND s.status = 200 GROUP BY 1, 2 ) SELECT b.user_type, b.sales_channel, b.is_ac, CASE WHEN s.total_ratings >= 0 AND s.total_ratings < 1.5 THEN '0 - 1.5' WHEN s.total_ratings >= 1.5 AND s.total_ratings < 2.5 THEN '1.5 - 2.5' WHEN s.total_ratings >= 2.5 AND s.total_ratings < 3 THEN '2.5 - 3' WHEN s.total_ratings >= 3 AND s.total_ratings < 3.5 THEN '3 - 3.5' WHEN s.total_ratings >= 3.5 AND s.total_ratings < 4 THEN '3.5 - 4' WHEN s.total_ratings >= 4 AND s.total_ratings < 4.5 THEN '4 - 4.5' WHEN s.total_ratings >= 4.5 AND s.total_ratings < 5 THEN '4.5 +' ELSE 'NA' END AS total_ratings, COUNT(DISTINCT b.tin) as total_txn_count, /* Same Day: Cast to DATE to compare just the calendar day */ COUNT(DISTINCT CASE WHEN DATE(b.issue_ist) = DATE(b.journey_ist) THEN tin END) AS same_day_txn_count, /* Same Hour: Keep as TIMESTAMP to calculate hours difference */ COUNT(DISTINCT CASE WHEN DATE_DIFF('hour', b.issue_ist, b.journey_ist) = 0 THEN tin END) AS same_hour_txn_count FROM base_data b LEFT JOIN ratings s ON b.mri_session_id = s.mri_session_id AND b.route_id = s.route_id GROUP BY 1,2,3,4 ORDER BY 1 DESC, 2, 3, 4, 5 DESC
